B=np.column_stack([np.ones(N),X,
 np.maximum(0,X[:,0:1]-np.arange(-3,3,1)),
 np.maximum(0,X[:,10:11]-np.arange(1,10,1)),
 ((X[:,0]>=.5)&(X[:,1]==1)&(X[:,9]==1)),
 ((X[:,0]<-2)&(X[:,6]==1)&(X[:,8]==0)),
 ((X[:,0]<0)&(X[:,1]==1)&(X[:,9]==1))])
Q=np.linalg.qr(B,mode="reduced")[0];r=y-Q@(Q.T@y)
print("RMSE with 3 groups",np.std(r))
bits=[];bn=[];bi=[]
for j in range(1,10):
 for b in [0,1]:
  bits.append(X[:,j]==b);bn.append(INPUTS[j]+"="+str(b));bi.append(j)
cuts=[];cn=[]
for j,ts in [(0,[-3,-2,-1,0,.5,1,1.5,2]),(10,[.5,1,1.5,2,3,4,5,6,7,8,9])]:
 for t in ts:
  cuts.append(X[:,j]<t);cn.append(INPUTS[j]+"<"+str(t))
  cuts.append(X[:,j]>=t);cn.append(INPUTS[j]+">="+str(t))
masks=[];names=[]
for j in range(len(bits)):
 for k in range(j+1,len(bits)):
  if bi[j]==bi[k]:continue
  m=bits[j]&bits[k]
  masks.append(m);names.append(bn[j]+" & "+bn[k])
  for c in range(len(cuts)):
   masks.append(m&cuts[c]);names.append(bn[j]+" & "+bn[k]+" & "+cn[c])
  for l in range(k+1,len(bits)):
   if bi[l] in [bi[j],bi[k]]:continue
   masks.append(m&bits[l]);names.append(bn[j]+" & "+bn[k]+" & "+bn[l])
 for c in range(len(cuts)):
  masks.append(bits[j]&cuts[c]);names.append(bn[j]+" & "+cn[c])
outs=[]
for i in range(0,len(masks),300):
 G=np.asarray(masks[i:i+300],float).T;n=G.sum(0)
 cross=Q.T@G;denom=n-np.sum(cross**2,axis=0);numer=r@G
 good=(n/N>.02)&(denom>10);gamma=numer/np.maximum(denom,1);sc=numer*gamma/N
 for q in np.where(good)[0]:outs.append((sc[q],names[i+q],gamma[q],n[q]/N))
for row in sorted(outs,reverse=True)[:35]:print(row)

